\label{Rockafellar_Theorem}
	Let $T \colon \mathbf{X} \multimap \mathbf{X}^*$ be a set-valued operator and let $\Gamma_0(\mathbf{X})$ denote the set of proper lower semicontinuous convex functions $f \colon \mathbf{X} \to \mathbb{R} \cup \{+\infty\}$. The following statements hold.
	\begin{enumerate}
		\item \emph{(Existence)} $T$ is cyclically monotone if and only if $T \subseteq \partial f$ for some $f \in \Gamma_0(\mathbf{X})$. Such an $f$ is called a convex potential of $T$.
		\item \emph{(Maximal cyclical monotonicity)} $T$ is maximal cyclically monotone if and only if $T = \partial f$ for some $f \in \Gamma_0(\mathbf{X})$.
		\item \emph{(Uniqueness)} If $\partial f = \partial g$ with $f, g \in \Gamma_0(\mathbf{X})$, then $f - g$ is constant. Thus, the convex potential of a maximal cyclically monotone operator is unique up to an additive constant.
		\item \emph{(Maximal monotonicity)} For every $f \in \Gamma_0(\mathbf{X})$, the operator $\partial f$ is maximal monotone.
	\end{enumerate}

\label{dfn_qc_cqm}
	\leavevmode
	\begin{enumerate}[(i)]
		\item A function $f \colon \mathbf{X} \to \mathbb{R} \cup \{+\infty\}$ is \emph{quasi-convex} if its sublevel sets $\{x \in \mathbf{X} : f(x) \leq \ell\}$ are convex for every $\ell \in \mathbb{R}$.
		\item A set-valued operator $T \colon \mathbf{X} \multimap \mathbf{X}^*$ is \emph{cyclically quasi-monotone} if for every sequence of points $x_0, \ldots, x_N \in \mathbf{X}$ satisfying $x_N = x_0$, and every $x^*_0 \in T(x_0), \ldots, x^*_{N-1} \in T(x_{N-1})$, the following inequality holds:
		\begin{equation}\tag{CQM}\label{cyclical_quasi_monotonicity}
			\min_{0 \leq i < N} \pair{x^*_i}{x_{i+1}-x_i} \leq 0.
		\end{equation}
		If this inequality is only required for $N = 2$, then $T$ is said to be \emph{quasi-monotone}.
	\end{enumerate}

\label{thm_afriat}
	Let $\mathcal D = \{(x_i,p_i)\}_{1 \leq i \leq n}$ be a finite data set with $p_i \in \mathopen]0,+\infty\mathclose[^d$. The following assertions are equivalent.
	\begin{enumerate}[(i)]
		\item $\mathcal D$ is rationalized by a locally non-satiated\footnote{A utility function is locally non-satiated if it admits no local maximizer.} utility function, which can moreover be chosen continuous and concave.
		\item $\mathcal D$ satisfies GARP: for every cycle $i_0, \ldots, i_N = i_0$ such that $\pair{p_{i_k}}{x_{i_{k+1}}} \leq \pair{p_{i_k}}{x_{i_k}}$ for every $k < N$, all these inequalities are equalities.
	\end{enumerate}

\label{thm_rader}
	For every lower semicontinuous preference relation $\preceq$ on a second-countable topological space $X$, there exists a lower semicontinuous function $f \colon X \to [0,1]$ such that
	\begin{equation}\label{potential_preference_relation_Rader}
		x \preceq y \iff f(x) \leq f(y)
	\end{equation}
	for every $x,y \in X$.

\label{cor_rader_separable}
	For every lower semicontinuous and quasi-convex preference relation $\preceq$ on a separable Banach space $\mathbf{X}$, there exists a quasi-convex lower semicontinuous function $f \colon \mathbf{X} \to [0,1]$ representing $\preceq$, meaning that
	\[\forall x,y \in \mathbf{X}, \qquad x \preceq y \iff f(x) \leq f(y).\]

\label{transitivity_properties}
	Let $T \colon \mathbf{X} \multimap \mathbf{X}^*$ be a cyclically quasi-monotone operator.
	\begin{enumerate}[(i)]
		\item\label{item_strict_pre-order} The relation $\prec_T$ is a strict preorder.
		\item\label{item_pre-order} The relation $\preceq_T$ is a preorder.
		\item\label{item_strict_implies_large} For every $x,y \in \mathbf{X}$,
		\begin{equation}\label{strict_implies_large}
			x \prec_T y \implies x \preceq_T y.
		\end{equation}
		\item\label{item_mixed_transitivity} The following mixed transitivity property holds: for every $x,y,z \in \mathbf{X}$,
		\begin{equation}\label{strlarstr}
			x \prec_T y \text{ and } y \preceq_T z \implies x \prec_T z.
		\end{equation}
	\end{enumerate}

\label{F_equals_normal_cone}
	Let $T \colon \mathbf{X} \multimap \mathbf{X}^*$ be a cyclically quasi-monotone operator. Then
	\begin{equation}\label{F_included_normal_cone}
		\forall x \in \mathbf{X}, \quad T(x) \subseteq \mathrm{N}_{C^T(x)}(x).
	\end{equation}
	If moreover $T$ is maximal cyclically quasi-monotone, then
	\[\forall x \in \mathbf{X}, \quad T(x) = \mathrm{N}_{C^T(x)}(x) = (S^T(x) - x)^\circ.\]

\label{convexity_stable_by_union}
	Let $T \colon \mathbf{X} \multimap \mathbf{X}^*$ be a maximal cyclically quasi-monotone operator on a smoothable Banach space $\mathbf{X}$. Then for every set of points $A \subseteq \mathbf{X}$,
	\[\bigcup_{x\in A} C^T(x) \text{ is a convex set}.\]

\label{pre-order_extension}
	For every preorder $\preceq$ on a set $X$, there exists a total preorder $\preceq'$ on $X$ that extends $\preceq$ and preserves its strict part, i.e., such that for every $x,y \in X$,
	\begin{align*}
		x \preceq y &\implies x \preceq' y,\\
		(x \preceq y \text{ and } y \not\preceq x) &\implies y \not\preceq' x.
	\end{align*}

Since $T(x) \neq \mathbf{X}^*$, $E = \operatorname{lin} T(x)$ is a proper vector subspace of $\mathbf{X}^*$. First of all, let us show that $C^T(x)$, and thus $S^T(x)$ as well, is included in $x +E^\perp$. We proceed by contraposition, considering $y \not\in x+E^\perp$. There exists $e^* \in E$ such that $\pair{e^*}{y-x} \neq 0$, and since $\pm e^* \in T(x)$ we get $\pair{y^*}{y-x} > 0$ for either $y^* = e^*$ or $y^* = -e^*$, thus $x \prec_T y$. By \Cref{transitivity_properties}, this implies that $y\not\in C^T(x)$.

	To show the desired result, it suffices to prove that the convex cone $\operatorname{cone}(S^T(x)-x)$, which is included in $E^\perp$, is not equal to $E^\perp$. Indeed, in that case, considering the associated polar cones in $E^\perp$, there exists a linear form on $E^\perp$ which is nonpositive on $S^T(x)-x$ and does not vanish identically, and any extension $x^* \in \mathbf{X}^*$ of this form satisfies the desired inclusion, as well as $x^* \notin E$. We proceed by contradiction, assuming that $\operatorname{cone}(S^T(x)-x) = E^\perp$. Thus there exists a finite subset $\mathcal{P}\subseteq S^T(x)$ such that $\operatorname{cone}(\mathcal{P}-x) = E^\perp$.

	Take $x_0 \in \mathcal{P}$. Since $x_0 \prec_T x$, there exists a $T$-ascending path $(z_0, \ldots, z_n)$ from $x_0$ to $x$. In particular, there exists $z_{n-1}^* \in T(z_{n-1})$ such that
	\begin{equation}\label{x_in_half_space}
		\pair{z_{n-1}^*}{x-z_{n-1}} > 0.
	\end{equation}
	Besides, if $n \geq 2$, then $x_0 \prec_T z_{n-1}$, and since $T$ is cyclically quasi-monotone, necessarily
	\begin{equation}\label{x0_in_half_space}
		\pair{z_{n-1}^*}{x_0 - z_{n-1}} \leq 0,
	\end{equation}
	which also holds trivially if $n = 1$, since then $z_{n-1} = x_0$.

	We claim that
	\begin{equation}\label{induction_step}
		\exists x_1 \in \mathcal{P}\setminus\{x_0\} \quad\text{such that}\quad x_0 \prec_T x_1.
	\end{equation}
	By contradiction, assume this is false. In that case we necessarily have
	\begin{equation}\label{x0_complement_in_half_space}
		\mathcal{P}\setminus\{x_0\} \subseteq \{y : \pair{z_{n-1}^*}{y-z_{n-1}} \leq 0\},
	\end{equation}
	because otherwise there would exist a point $y \in \mathcal{P}\setminus\{x_0\}$ such that $\pair{z_{n-1}^*}{y-z_{n-1}} > 0$, thus $z_{n-1} \prec_T y$, hence $x_0 \prec_T y$. From \labelcref{x0_in_half_space} and \labelcref{x0_complement_in_half_space} we get
	\[\mathcal{P} \subseteq \{y : \pair{z_{n-1}^*}{y-z_{n-1}} \leq 0\},\]
	and since $\{y : \pair{z_{n-1}^*}{y-z_{n-1}} \leq 0\} \subseteq \{y : \pair{z_{n-1}^*}{y-x} \leq 0\}$ by \labelcref{x_in_half_space}, we deduce that
	\[\mathcal{P} - x \subseteq \{v \in E^\perp : \pair{z_{n-1}^*}{v} \leq 0\}.\]
	Since $z_{n-1} \in S^T(x) \subseteq x + E^\perp$, we have $x - z_{n-1} \in E^\perp$, so that the linear form $\pair{z_{n-1}^*}{\cdot}$ does not vanish identically on $E^\perp$ by \labelcref{x_in_half_space}. Thus the right-hand side is a closed half-space of $E^\perp$, which contradicts the fact that $\operatorname{cone}(\mathcal{P}-x) = E^\perp$, and we have proved \labelcref{induction_step}.

	Since $x_0 \in \mathcal{P}$ was arbitrary, every point of $\mathcal{P}$ is $\prec_T$-smaller than another point of $\mathcal{P}$. Starting from any point of $\mathcal{P}$, we may thus build a sequence $(x_i)_{i \in \mathbb{N}}$ in $\mathcal{P}$ such that $x_i \prec_T x_{i+1}$ for every $i$. Since $\mathcal{P}$ is finite, we have $x_j = x_i$ for some $i < j$, hence $x_i \prec_T x_{i+1} \prec_T \cdots \prec_T x_j = x_i$ yields a $T$-ascending cycle: a contradiction with $T$ being cyclically quasi-monotone.

\label{relative_interior}
	Let $C$ be a nonempty convex subset of $\mathbf{X}$. The following statements hold.
	\begin{enumerate}[(a)]
		\item\label{item_ri_dense} $\operatorname{ri} C$ is nonempty and dense in $\operatorname{cl} C$.
		\item\label{item_ri_cone} For every $x \in C$, we have $x \in \operatorname{ri} C$ if and only if $\operatorname{cone} (C-x)$ is a vector subspace of $\mathbf{X}$, if and only if $\operatorname{\overline{cone}} (C-x)$ is a vector subspace of $\mathbf{X}$.
	\end{enumerate}

\label{lem_equality_cones}
	Let $f$ be a lower semicontinuous quasi-convex function which is essentially non-satiated. If $x \notin \operatorname{arg\,min} f$ then
	\[\operatorname{\overline{cone}} (S^{\mathrm{N} f}_1(x)-x) = \operatorname{\overline{cone}} (S^{\mathrm{N} f}(x)-x) = \operatorname{\overline{cone}} (\{f < f(x)\}-x) = \operatorname{\overline{cone}} (\{f \leq f(x)\}-x).\]
